def count_With_Odd_SetBits(n):
    """
    Return the count of integers from 1 to n inclusive
    that have an odd number of set bits.
    """
    if n <= 0:
        return 0

    count = 0
    prefix_parity = 0

    for i in range(n.bit_length() - 1, -1, -1):
        if (n >> i) & 1:
            if i:
                count += 1 << (i - 1)
            else:
                count += prefix_parity
            prefix_parity ^= 1

    return count + prefix_parity
```

