def list_to_float(data):
    def convert(item):
        if isinstance(item, str):
            try:
                return float(item)
            except ValueError:
                return item
        if isinstance(item, (list, tuple)):
            converted = [convert(x) for x in item]
            return tuple(converted) if isinstance(item, tuple) else converted
        return item

    return str(convert(data))
