def first(arr, target, n=None):
    if not arr:
        return -1

    high = len(arr) - 1 if n is None else min(n, len(arr) - 1)
    low = 0
    ans = -1

    while low <= high:
        mid = (low + high) // 2

        if arr[mid] == target:
            ans = mid
            high = mid - 1
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1

    return ans
