def max_product(arr, n=None):
    if arr is None:
        return 0

    if n is None:
        a = list(arr)
    else:
        a = list(arr)[:max(0, int(n))]

    if not a:
        return 0

    values = sorted(set(a))
    index = {v: i + 1 for i, v in enumerate(values)}
    size = len(values)

    NEG_INF = float("-inf")
    POS_INF = float("inf")

    max_tree = [NEG_INF] * (size + 1)
    min_tree = [POS_INF] * (size + 1)

    def update_max(i, val):
        while i <= size:
            if val > max_tree[i]:
                max_tree[i] = val
            i += i & -i

    def query_max(i):
        res = NEG_INF
        while i > 0:
            if max_tree[i] > res:
                res = max_tree[i]
            i -= i & -i
        return res

    def update_min(i, val):
        while i <= size:
            if val < min_tree[i]:
                min_tree[i] = val
            i += i & -i

    def query_min(i):
        res = POS_INF
        while i > 0:
            if min_tree[i] < res:
                res = min_tree[i]
            i -= i & -i
        return res

    best = NEG_INF

    for x in a:
        i = index[x]

        qmax = query_max(i - 1)
        qmin = query_min(i - 1)

        mx = x
        mn = x

        if qmax != NEG_INF:
            prod = qmax * x
            if prod > mx:
                mx = prod
            if prod < mn:
                mn = prod

        if qmin != POS_INF:
            prod = qmin * x
            if prod > mx:
                mx = prod
            if prod < mn:
                mn = prod

        update_max(i, mx)
        update_min(i, mn)

        if mx > best:
            best = mx

    return 0 if best == NEG_INF else best
