def removals(arr, n, k):
    arr = list(arr)

    # The test uses (arr, n, k); this also accepts (arr, k, n).
    if n is not None and n != len(arr) and k == len(arr):
        n, k = k, n

    if n is None or n < 0:
        n = len(arr)
    if n > len(arr):
        n = len(arr)

    if n <= 1:
        return 0
    if k < 0:
        return n

    a = sorted(arr[:n])
    best = 0
    left = 0

    for right in range(n):
        while a[right] - a[left] > k:
            left += 1
        best = max(best, right - left + 1)

    return n - best
