def count_duplic(lst):
    if not lst:
        return ([], [])

    values = []
    counts = []

    current = lst[0]
    count = 1

    for num in lst[1:]:
        if num == current:
            count += 1
        else:
            values.append(current)
            counts.append(count)
            current = num
            count = 1

    values.append(current)
    counts.append(count)

    return (values, counts)
